func TestReadValueContentAcceptsWhitespaceBetweenElements(t *testing.T) {
	containers := []struct {
		name     string
		prefix   string
		suffix   string
		expected ourtypes.JsonValue
	}{
		{
			name:     "array",
			prefix:   "<array><data><value>",
			suffix:   "</value></data></array>",
			expected: ourtypes.JsonArray{"hello"},
		},
		{
			name:     "object",
			prefix:   "<struct><member><name>key</name><value>",
			suffix:   "</value></member></struct>",
			expected: ourtypes.JsonObject{"key": "hello"},
		},
	}
	separators := []struct {
		name string
		text string
	}{
		{"compact", ""},
		{"lf", "\n  "},
		{"tab_indentation", "\n\t"},
		{"crlf", "\r\n  "},
		{"comment", "<!-- comment -->"},
		{"comment_with_whitespace", "\n  <!-- comment -->\n  "},
	}
	for _, container := range containers {
		for _, separator := range separators {
			t.Run(container.name+"/"+separator.name, func(t *testing.T) {
				text := container.prefix + "<string>hello</string>" + container.suffix
				text = strings.ReplaceAll(text, "><", ">"+separator.text+"<")
				decoder := xml.NewDecoder(strings.NewReader(text))
				current, err := decoder.Token()
				if err != nil {
					t.Fatal(err)
				}
				got, _, err := ourxmlrpc.ReadValueContent(decoder, current)
				if err != nil {
					t.Fatalf("Expected no error, but got: %v", err)
				}
				if !reflect.DeepEqual(got, container.expected) {
					t.Fatalf("Expected %#v, but got %#v", container.expected, got)
				}
			})
		}
	}
}

func TestReadValueContentPreservesStringWhitespace(t *testing.T) {
	cases := []struct {
		name string
		text string
	}{
		{"empty", ""},
		{"spaces", " hello "},
		{"whitespace_only", " \t\n "},
		{"mixed", " \thello\n "},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			text := "<array><data><value>\n  <string>" + c.text +
				"</string>\n  </value></data></array>"
			decoder := xml.NewDecoder(strings.NewReader(text))
			current, err := decoder.Token()
			if err != nil {
				t.Fatal(err)
			}
			got, _, err := ourxmlrpc.ReadValueContent(decoder, current)
			if err != nil {
				t.Fatalf("Expected no error, but got: %v", err)
			}
			expected := ourtypes.JsonArray{c.text}
			if !reflect.DeepEqual(got, expected) {
				t.Fatalf("Expected %#v, but got %#v", expected, got)
			}
		})
	}
}

func TestReadValueContentRejectsInvalidValueEnd(t *testing.T) {
	cases := []struct {
		name   string
		suffix string
	}{
		{"trailing_text", "unexpected</value></data></array>"},
		{"text_after_whitespace", "\n  unexpected</value></data></array>"},
		{"extra_child", "<string>extra</string></value></data></array>"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			text := "<array><data><value><string>hello</string>" + c.suffix
			decoder := xml.NewDecoder(strings.NewReader(text))
			current, err := decoder.Token()
			if err != nil {
				t.Fatal(err)
			}
			_, _, err = ourxmlrpc.ReadValueContent(decoder, current)
			if err == nil {
				t.Fatal("Expected an error, but got none")
			}
		})
	}
}

